// One item per Data Table row id that went into the brief, for the update node.
const ids = ($('Collect').first().json.briefed_ids || [])
  .filter((x) => x !== null && x !== undefined);
return ids.map((id) => ({ json: { row_id: id } }));

// One item per article. Row data comes from Get row(s) via pairedItem;
// the fetched page text (if any) is on $json.data from the Fetch URL node.
const row = $('Get row(s)').item.json;
const resp = $json || {};

function clean(h) {
  return String(h || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&[a-z#0-9]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

let excerpt = '';
if (resp && resp.data && !resp.error) excerpt = clean(resp.data).slice(0, 6000);

const SYS = [
  'You are a precise technical research assistant. You are given ONE article: its title, URL, a curator note, and a text excerpt that may be truncated or empty.',
  '',
  'Work in this order and make AT MOST 2 tool calls total — never keep retrying a blocked site:',
  '1. If the excerpt clearly contains the article substance, summarise from it (no tool calls).',
  '2. Otherwise make ONE attempt to fetch the URL with your web tools.',
  '3. If the page is still not usable (anti-bot / JS challenge / paywall / login wall / 404 / only markup), do ONE GENERAL WEB SEARCH about the article topic or title and summarise what reliable sources say about that subject.',
  '',
  'Output EXACTLY these three lines, nothing else:',
  'Topic: <one line>',
  'Source: <"article" if you summarised the actual page or excerpt | "general web search" if you used step 3>',
  'Summary: <2 to 3 paragraphs of plain prose — key technical points, findings or arguments, and why they matter. If Source is "general web search", begin the first sentence with exactly: Based on general web search (the original article could not be accessed): . No bullet lists, no preamble, no commentary about your tools or process.>',
].join('\n');

const USER = 'TITLE: ' + (row.title || 'Untitled') +
  '\nURL: ' + (row.url || '') +
  '\nCURATOR NOTE: ' + (row.why || '') +
  '\n\nEXCERPT:\n' + (excerpt || '(none - fetch the URL, or fall back to a general web search)');

return {
  json: {
    row_id: row.id,
    title: row.title || 'Untitled',
    url: row.url || '',
    category: row.category || '',
    bucket: row.bucket || '',
    score: row.score != null ? row.score : '',
    messages: [
      { role: 'system', content: SYS },
      { role: 'user', content: USER },
    ],
  },
};

// Assemble one markdown brief from the per-item Hermes responses.
const results = $input.all();
const prepped = $('Prep item').all().map((x) => x.json);
const today = new Date().toISOString().slice(0, 10);

const lines = [
  `# Miniflux Curator Brief — ${today}`,
  '',
  `${prepped.length} curated item(s) (curator score >= 5). Per-article summaries by Hermes.`,
  '',
];
const briefed_ids = [];

prepped.forEach((p, i) => {
  if (p.row_id !== undefined && p.row_id !== null) briefed_ids.push(p.row_id);
  const r = results[i] ? results[i].json : {};
  let text = '';
  if (r && r.choices && r.choices[0] && r.choices[0].message) {
    text = String(r.choices[0].message.content || '').trim();
  } else if (r && r.error) {
    text = `(summary failed: ${r.error.message || r.error})`;
  }
  lines.push(`## ${i + 1}. ${p.title}`);
  lines.push(p.url);
  lines.push(`*${p.category} · ${p.bucket} · score ${p.score}*`);
  lines.push('');
  lines.push(text || '(no summary returned)');
  lines.push('');
});

return [{ json: { brief: lines.join('\n'), total_items: prepped.length, briefed_ids, generated: today } }];
